/**
 * @name Unsafe HTTP request handling
 * @description Potential SSRF or request smuggling via HTTP requests
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-http
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module UnsafeHttpConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      (
        // urllib.request.urlopen
        call = API::moduleImport("urllib").getMember("request").getMember("urlopen").getACall()
        or
        // requests.get, post, etc.
        call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "options", "patch"]).getACall()
        or
        // httpx.get, post, etc.
        call = API::moduleImport("httpx").getMember(["get", "post", "put", "delete", "head", "options", "patch"]).getACall()
        or
        // aiohttp ClientSession methods
        call = API::moduleImport("aiohttp").getMember("ClientSession").getMember(["get", "post", "put", "delete", "head", "options", "patch"]).getACall()
      )
      and sink = call.getArg(0)
    )
  }
}

module UnsafeHttpFlow = TaintTracking::Global<UnsafeHttpConfig>;
import UnsafeHttpFlow::PathGraph

from UnsafeHttpFlow::PathNode source, UnsafeHttpFlow::PathNode sink
where UnsafeHttpFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SSRF from $@.", source.getNode(), "user input"

