/**
 * @name Authentication token exposure
 * @description Potential exposure of authentication tokens or API keys
 * @kind path-problem
 * @problem.severity error
 * @id py/auth-token-exposure
 * @tags security
 *        external/cwe/cwe-798
 *        external/cwe/cwe-200
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module AuthTokenConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // Logging authentication tokens
      call = API::moduleImport("logging").getMember(["debug", "info", "warning", "error", "critical"]).getACall()
      and sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // HTTP header setting with sensitive data
      call = API::moduleImport("requests").getMember(["headers", "update"]).getACall()
      and sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // Writing to files or network with sensitive data
      call = API::moduleImport("builtins").getMember(["print", "open", "write"]).getACall()
      and sink = call.getArg(0)
    )
  }
}

module AuthTokenFlow = TaintTracking::Global<AuthTokenConfig>;
import AuthTokenFlow::PathGraph

from AuthTokenFlow::PathNode source, AuthTokenFlow::PathNode sink
where AuthTokenFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential authentication token exposure from $@.", source.getNode(), "user input"
